import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"캐싱","description":"","frontmatter":{},"headers":[],"relativePath":"ko/advanced/caching.md","filePath":"ko/advanced/caching.md","lastUpdated":1784903584000}'),c={name:"ko/advanced/caching.md"};function i(o,a,d,l,p,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="캐싱" tabindex="-1">캐싱 <a class="header-anchor" href="#캐싱" aria-label="Permalink to &quot;캐싱&quot;">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>swag2mcp는 다운로드한 명세 파일을 캐시하여 이후 실행 시 MCP 서버가 더 빠르게 시작됩니다. 매번 동일한 명세 파일을 다운로드하는 대신 캐시된 복사본을 재사용합니다.</p><h2 id="캐싱-작동-방식" tabindex="-1">캐싱 작동 방식 <a class="header-anchor" href="#캐싱-작동-방식" aria-label="Permalink to &quot;캐싱 작동 방식&quot;">​</a></h2><p>원격 URL로 spec을 추가하면 swag2mcp가 다운로드하여 <code>cache/</code> 디렉토리에 저장합니다. 다음 시작 시 캐시된 복사본이 여전히 유효한지 확인합니다. 유효하면 다운로드를 건너뜁니다.</p><h3 id="캐시되는-항목" tabindex="-1">캐시되는 항목 <a class="header-anchor" href="#캐시되는-항목" aria-label="Permalink to &quot;캐시되는 항목&quot;">​</a></h3><table tabindex="0"><thead><tr><th>소스</th><th>동작</th></tr></thead><tbody><tr><td><strong>원격 URL</strong> (http/https)</td><td>항상 캐시됨. 한 번 다운로드 후 캐시가 만료될 때까지 재사용</td></tr><tr><td><strong>로컬 파일 (<code>specs/</code> 내)</strong></td><td><code>specs/</code> 디렉토리에서 직접 사용. 캐시되지 않음 — 변경 사항이 즉시 반영됨</td></tr><tr><td><strong>로컬 파일 (<code>specs/</code> 외)</strong></td><td>캐시로 복사됨. 소스 파일이 변경되면(수정 시간) 캐시가 무효화됨</td></tr></tbody></table><h3 id="캐시-만료-ttl" tabindex="-1">캐시 만료 (TTL) <a class="header-anchor" href="#캐시-만료-ttl" aria-label="Permalink to &quot;캐시 만료 (TTL)&quot;">​</a></h3><p>각 캐시 파일은 <strong>1시간에서 48시간</strong> 사이의 무작위 만료 시간을 받습니다. 무작위성은 모든 캐시 파일이 동시에 만료되는 것을 방지합니다(다운로드 폭주 현상 방지).</p><ul><li>TTL은 MCP 서버가 시작될 때마다 재설정됩니다</li><li>캐시 파일이 TTL 내에 있으면 재사용됩니다</li><li>TTL이 만료되면 파일이 다시 다운로드됩니다</li></ul><h3 id="캐시-구조" tabindex="-1">캐시 구조 <a class="header-anchor" href="#캐시-구조" aria-label="Permalink to &quot;캐시 구조&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # 캐시된 명세 파일</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # 메타데이터 (소스, TTL, 캐시 시간)</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>캐시 키는 명세 파일 URL 또는 경로에서 파생됩니다. 각 캐시 파일에는 캐시된 시간과 만료 시간을 저장하는 <code>.meta</code> 파일이 함께 있습니다.</p><h2 id="캐시-관리" tabindex="-1">캐시 관리 <a class="header-anchor" href="#캐시-관리" aria-label="Permalink to &quot;캐시 관리&quot;">​</a></h2><h3 id="강제-새로고침" tabindex="-1">강제 새로고침 <a class="header-anchor" href="#강제-새로고침" aria-label="Permalink to &quot;강제 새로고침&quot;">​</a></h3><p><code>swag2mcp update</code>를 실행하여 전체 캐시를 지우고 모든 명세 파일을 다시 다운로드하세요:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>설정을 검증하고, 캐시를 지우고, 모든 것을 새로 다운로드합니다.</p><h3 id="수동으로-캐시-지우기" tabindex="-1">수동으로 캐시 지우기 <a class="header-anchor" href="#수동으로-캐시-지우기" aria-label="Permalink to &quot;수동으로 캐시 지우기&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>모든 캐시된 명세 파일과 저장된 API 응답을 제거합니다. 다음에 MCP 서버를 시작할 때 모든 명세가 다시 다운로드됩니다.</p><h3 id="자동-정리" tabindex="-1">자동 정리 <a class="header-anchor" href="#자동-정리" aria-label="Permalink to &quot;자동 정리&quot;">​</a></h3><p>MCP 서버가 시작될 때(<code>swag2mcp mcp</code>) 48시간보다 오래된 저장된 API 응답이 자동으로 제거됩니다. 이는 <code>responses/</code> 디렉토리가 무한정 커지는 것을 방지합니다.</p><h2 id="중요-참고-사항" tabindex="-1">중요 참고 사항 <a class="header-anchor" href="#중요-참고-사항" aria-label="Permalink to &quot;중요 참고 사항&quot;">​</a></h2><ul><li><strong><code>specs/</code>의 로컬 파일은 캐시되지 않음</strong> — <code>specs/</code> 디렉토리에서 명세 파일을 직접 편집하면 캐시를 지우지 않고도 변경 사항이 즉시 반영됩니다</li><li><strong>원격 URL은 항상 캐시됨</strong> — <code>swag2mcp update</code> 또는 <code>swag2mcp clean</code>을 실행하는 것 외에는 원격 URL의 캐시를 우회할 방법이 없습니다</li><li><strong>캐시는 로컬</strong> — 디스크에 저장되며 머신 간에 동기화되지 않습니다. 머신 간에 명세를 전송하려면 <code>swag2mcp export</code>와 <code>swag2mcp import</code>를 사용하세요</li></ul>`,25)])])}const g=e(c,[["render",i]]);export{b as __pageData,g as default};
